// The Mesh envelope codec, written and read by the codec generated from the
// standard document sce:std/mesh/envelope.scxml (sce/src/mesh/generated/,
// regenerated by sce/src/mesh/generate_envelope.sh). Every backend generates
// that same document, so the envelope's CBOR is one implementation six times
// over rather than a C++ codec the others were held to: its keys, its six
// required entries, its exact 16-byte identifiers, its string and payload
// bounds and its enum value sets are the document's, and a wire this file
// refuses is one every backend refuses (SCE_FORGE.md §4.6.1).
//
// What remains here is the conversion between the runtime's MeshEnvelope —
// the type every transport and the engine bridge already hold — and the
// generated value, which is made by its constructor, each text and byte string
// within its bound, and read by its accessors (docs/adr/0081 step 4).

#include "mesh/MeshEnvelopeCodec.h"

#include "generated/envelope.h"

#include <algorithm>
#include <array>
#include <cstdint>
#include <optional>
#include <string>
#include <type_traits>
#include <utility>
#include <vector>

namespace SCE::Mesh {

namespace {

namespace gen = ::SCE::Generated;
using GenEnvelope = gen::Envelope::Envelope;

// What the generated value presents an entry as: a text or a byte string as
// its bound's view, made by its `make`, which refuses one past the bound.
using Id = decltype(std::declval<const GenEnvelope &>().id());
using Text = decltype(std::declval<const GenEnvelope &>().source());
using Data = decltype(std::declval<const GenEnvelope &>().data());

// The runtime holds each entry in a type of its own; the generated value
// holds it within the document's bound. An entry outside it is no value of the
// generated codec, and `make` says so.
std::optional<Id> boundedId(const std::array<uint8_t, 16> &v) {
    return Id::make(::SCE::Forge::Span<const uint8_t>(v.data(), v.size()));
}

std::optional<Text> boundedText(const std::string &v) {
    return Text::make(v);
}

// An optional entry within its bound: absent where the runtime holds none,
// `false` where the one it holds is past the bound.
template <typename B, typename T, typename F>
bool boundedOptional(const std::optional<T> &v, F make, std::optional<B> &out) {
    if (!v) {
        return true;
    }
    out = make(*v);
    return out.has_value();
}

std::array<uint8_t, 16> array16(const Id &v) {
    std::array<uint8_t, 16> out{};
    std::copy(v.inner().begin(), v.inner().end(), out.begin());
    return out;
}

std::string text(const Text &v) {
    return std::string(v.inner());
}

template <typename T, typename F> auto mapOptional(const std::optional<T> &v, F f) -> std::optional<decltype(f(*v))> {
    if (!v) {
        return std::nullopt;
    }
    return f(*v);
}

// The runtime's enums and the generated ones declare the same values over
// the same carriers (sce/include/mesh/{PatternKind,PayloadCodec,RpcStatus}.h
// mirror stdlib/mesh/*.scxml), so a conversion is the carrier's number.
gen::PatternKind::PatternKind toGenerated(PatternKind v) {
    return static_cast<gen::PatternKind::PatternKind>(static_cast<std::underlying_type_t<PatternKind>>(v));
}

gen::PayloadCodec::PayloadCodec toGenerated(PayloadCodec v) {
    return static_cast<gen::PayloadCodec::PayloadCodec>(static_cast<std::underlying_type_t<PayloadCodec>>(v));
}

gen::RpcStatus::RpcStatus toGenerated(RpcStatus v) {
    return static_cast<gen::RpcStatus::RpcStatus>(static_cast<std::underlying_type_t<RpcStatus>>(v));
}

PatternKind toRuntime(gen::PatternKind::PatternKind v) {
    return static_cast<PatternKind>(gen::PatternKind::to_underlying(v));
}

PayloadCodec toRuntime(gen::PayloadCodec::PayloadCodec v) {
    return static_cast<PayloadCodec>(gen::PayloadCodec::to_underlying(v));
}

RpcStatus toRuntime(gen::RpcStatus::RpcStatus v) {
    return static_cast<RpcStatus>(gen::RpcStatus::to_underlying(v));
}

// A causal route's vector (key 20) is a list of the record
// sce:std/mesh/causal_entry.scxml declares, which the generated value presents
// as a view of that schema's own payload type within the list's bound of 64,
// made by its `make`, which refuses a longer one. CausalEntry is the runtime's
// spelling of the same three fields.
using GenCausalEntry = gen::CausalEntry::CausalEntryPayload;
using CausalVector = decltype(std::declval<const GenEnvelope &>().causal_vector())::value_type;

std::vector<GenCausalEntry> causalToGenerated(const std::vector<CausalEntry> &v) {
    std::vector<GenCausalEntry> out;
    out.reserve(v.size());
    for (const auto &entry : v) {
        GenCausalEntry g;
        g.hi = entry.hi;
        g.lo = entry.lo;
        g.seq = entry.seq;
        out.push_back(g);
    }
    return out;
}

std::vector<CausalEntry> causalToRuntime(const CausalVector &v) {
    std::vector<CausalEntry> out;
    out.reserve(v.size());
    for (const auto &g : v) {
        CausalEntry entry;
        entry.hi = g.hi;
        entry.lo = g.lo;
        entry.seq = g.seq;
        out.push_back(entry);
    }
    return out;
}

// The generated value of `env`, or none where an entry lies past the bound the
// document states for it: a string over 256 KiB, a payload over
// kMaxEnvelopeBytes, a causal vector of more than 64 entries. The views it is
// made of read `env`, and the value copies what they view.
std::optional<GenEnvelope> toGenerated(const MeshEnvelope &env) {
    const auto id = boundedId(env.id);
    const auto source = boundedText(env.source);
    const auto eventType = boundedText(env.type);
    const auto data = Data::make(env.data);
    if (!id || !source || !eventType || !data) {
        return std::nullopt;
    }
    std::optional<Text> subject, replyTo, rpcErrorMessage, parallelId, regionId, childSessionId;
    std::optional<Id> correlationId, invokeId, routingId;
    if (!boundedOptional(env.subject, boundedText, subject) || !boundedOptional(env.reply_to, boundedText, replyTo) ||
        !boundedOptional(env.rpc_error_message, boundedText, rpcErrorMessage) ||
        !boundedOptional(env.parallel_id, boundedText, parallelId) ||
        !boundedOptional(env.region_id, boundedText, regionId) ||
        !boundedOptional(env.child_session_id, boundedText, childSessionId) ||
        !boundedOptional(env.correlation_id, boundedId, correlationId) ||
        !boundedOptional(env.invoke_id, boundedId, invokeId) ||
        !boundedOptional(env.routing_id, boundedId, routingId)) {
        return std::nullopt;
    }
    // The vector's records in the generated payload type, which the view of
    // them reads until the value is made and copies them.
    std::vector<GenCausalEntry> causalRecords;
    std::optional<CausalVector> causalVector;
    if (!boundedOptional(
            env.causal_vector,
            [&causalRecords](const std::vector<CausalEntry> &v) {
                causalRecords = causalToGenerated(v);
                return CausalVector::make(causalRecords);
            },
            causalVector)) {
        return std::nullopt;
    }
    // qos (key 13) is reserved and never written: no transport consumes it,
    // and the standard document does not declare it.
    return GenEnvelope{
        /*id=*/*id,
        /*source=*/*source,
        /*event_type=*/*eventType,
        /*pattern=*/toGenerated(env.pattern),
        /*datacontenttype=*/toGenerated(env.datacontenttype),
        /*data=*/*data,
        /*subject=*/subject,
        /*correlation_id=*/correlationId,
        /*reply_to=*/replyTo,
        /*invoke_id=*/invokeId,
        /*rpc_status=*/mapOptional(env.rpc_status, [](RpcStatus s) { return toGenerated(s); }),
        /*rpc_error_message=*/rpcErrorMessage,
        /*deadline_unix_ms=*/env.deadline_unix_ms,
        /*sequence_no=*/env.sequence_no,
        /*routing_id=*/routingId,
        /*parallel_id=*/parallelId,
        /*region_id=*/regionId,
        /*child_session_id=*/childSessionId,
        /*causal_epoch=*/env.causal_epoch,
        /*causal_vector=*/causalVector,
    };
}

MeshEnvelope toRuntime(const GenEnvelope &g) {
    MeshEnvelope env;
    env.id = array16(g.id());
    env.source = text(g.source());
    env.type = text(g.event_type());
    env.pattern = toRuntime(g.pattern());
    env.datacontenttype = toRuntime(g.datacontenttype());
    env.data.assign(g.data().inner().begin(), g.data().inner().end());
    env.subject = mapOptional(g.subject(), text);
    env.correlation_id = mapOptional(g.correlation_id(), array16);
    env.reply_to = mapOptional(g.reply_to(), text);
    env.invoke_id = mapOptional(g.invoke_id(), array16);
    env.rpc_status = mapOptional(g.rpc_status(), [](gen::RpcStatus::RpcStatus s) { return toRuntime(s); });
    env.rpc_error_message = mapOptional(g.rpc_error_message(), text);
    env.deadline_unix_ms = g.deadline_unix_ms();
    env.sequence_no = g.sequence_no();
    env.routing_id = mapOptional(g.routing_id(), array16);
    env.parallel_id = mapOptional(g.parallel_id(), text);
    env.region_id = mapOptional(g.region_id(), text);
    env.child_session_id = mapOptional(g.child_session_id(), text);
    env.causal_epoch = g.causal_epoch();
    env.causal_vector = mapOptional(g.causal_vector(), causalToRuntime);
    return env;
}

}  // namespace

std::vector<uint8_t> encodeEnvelope(const MeshEnvelope &env) {
    // SCE_MESH.md §mesh-7.5 mesh-native serialization: this is the encode half
    // of the single shared codec every byte-stream transport uses. The section
    // pins one canonical wire format for SCE↔SCE traffic — a CBOR-encoded
    // MeshEnvelope — so SOME/IP, Zenoh and custom_tcp call this directly and
    // SHM calls it inside ShmChannel rather than each carrying its own format.
    // Schema-free by design: the payload rides as opaque bytes.
    //
    // An envelope with an entry past its bound — a string over 256 KiB, a
    // payload over kMaxEnvelopeBytes — is refused here, as every decoder
    // refuses it, rather than written for the receiver to refuse: it has no
    // generated value.
    const auto generated = toGenerated(env);
    if (!generated) {
        return {};
    }
    return generated->encode_to_vec();
}

bool decodeEnvelope(const uint8_t *raw, std::size_t len, MeshEnvelope &out) {
    // SCE_MESH.md §mesh-7.5 mesh-native serialization: the decode half of the
    // shared codec. Symmetry with encodeEnvelope() is what makes the wire
    // format canonical rather than per-transport — a receiver reconstructs the
    // envelope without knowing which transport carried it.
    if (raw == nullptr || len == 0) {
        return false;
    }
    ::SCE::Forge::SceCursor cursor(raw, len);
    const auto decoded = GenEnvelope::decode(cursor);
    if (!decoded) {
        return false;
    }
    out = toRuntime(*decoded);
    return true;
}

}  // namespace SCE::Mesh
